"/**
 * FeedForward API Client
 * Wraps backend endpoints for reservations, chef demand, black stars, and waste routing.
 */

const API_BASE = window.location.origin;

export const api = {
  // Users
  async getUsers(role = null, partition = null) {
    const params = new URLSearchParams();
    if (role) params.append('role', role);
    if (partition) params.append('partition', partition);
    const res = await fetch(`${API_BASE}/api/users?${params.toString()}`);
    return res.json();
  },

  async getUser(userId) {
    const res = await fetch(`${API_BASE}/api/users/${userId}`);
    return res.json();
  },

  // Meals & Menus
  async getMeals(partition = null) {
    const params = new URLSearchParams();
    if (partition) params.append('partition_type', partition);
    const res = await fetch(`${API_BASE}/api/meals?${params.toString()}`);
    return res.json();
  },

  async createMeal(mealData) {
    const res = await fetch(`${API_BASE}/api/meals`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(mealData),
    });
    return res.json();
  },

  // Chef Demand Forecasting
  async getChefDemand(mealId) {
    const res = await fetch(`${API_BASE}/api/chef/demand/${mealId}`);
    return res.json();
  },

